CREATE TABLE newsletter_subscription (id UUID PRIMARY KEY,email VARCHAR(320) UNIQUE NOT NULL,status VARCHAR(20) NOT NULL,preferences CLOB DEFAULT '{}',source_ip VARCHAR(64),confirmed_at TIMESTAMP WITH TIME ZONE,unsubscribed_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE NOT NULL,updated_at TIMESTAMP WITH TIME ZONE NOT NULL);
CREATE TABLE newsletter_segment(id UUID PRIMARY KEY,name VARCHAR(200) UNIQUE NOT NULL,segment_type VARCHAR(20),criteria CLOB,static_subscription_ids CLOB,created_at TIMESTAMP WITH TIME ZONE,updated_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE newsletter_campaign(id UUID PRIMARY KEY,subject VARCHAR(500),content CLOB,cms_content_id UUID,segment_id UUID,targeting CLOB,status VARCHAR(20),scheduled_at TIMESTAMP WITH TIME ZONE,sent_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE,updated_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE outbound_email(id UUID PRIMARY KEY,subscription_id UUID,campaign_id UUID,message_type VARCHAR(30),recipient VARCHAR(320),subject VARCHAR(500),body CLOB,status VARCHAR(20),attempt_count INT DEFAULT 0,max_attempts INT DEFAULT 5,next_attempt_at TIMESTAMP WITH TIME ZONE,provider_message_id VARCHAR(255),last_error CLOB,created_at TIMESTAMP WITH TIME ZONE,sent_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE email_suppression(id UUID PRIMARY KEY,email VARCHAR(320) UNIQUE,reason VARCHAR(50),source VARCHAR(100),details CLOB,created_at TIMESTAMP WITH TIME ZONE,expires_at TIMESTAMP WITH TIME ZONE);
CREATE TABLE opt_in_token(id UUID PRIMARY KEY,subscription_id UUID,token_hash VARCHAR(64) UNIQUE,expires_at TIMESTAMP WITH TIME ZONE,consumed_at TIMESTAMP WITH TIME ZONE,created_at TIMESTAMP WITH TIME ZONE);
